import{_ as e,o,c as r,ag as i}from"./chunks/framework.ndCQWiBJ.js";const u=JSON.parse('{"title":"O Fio — Edição Especial Consolidada, 14/10/2026","description":"Retrospectiva consolidada do dia: votação da PEC da escala 6x1 no Senado, aceleração da inflação nos EUA e reorganização no setor de tecnologia","frontmatter":{"title":"O Fio — Edição Especial Consolidada, 14/10/2026","description":"Retrospectiva consolidada do dia: votação da PEC da escala 6x1 no Senado, aceleração da inflação nos EUA e reorganização no setor de tecnologia","date":"2026-10-14T00:00:00.000Z","edition":"especial"},"headers":[],"relativePath":"edicoes/2026-10-14-especial.md","filePath":"edicoes/2026-10-14-especial.md","lastUpdated":1792011766000}'),s={name:"edicoes/2026-10-14-especial.md"};function t(n,a,l,d,c,m){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="senado-vota-pec-do-fim-da-escala-6x1-em-dia-marcado-por-inflacao-nos-eua-e-cortes-em-big-techs" tabindex="-1">Senado vota PEC do fim da escala 6x1 em dia marcado por inflação nos EUA e cortes em big techs <a class="header-anchor" href="#senado-vota-pec-do-fim-da-escala-6x1-em-dia-marcado-por-inflacao-nos-eua-e-cortes-em-big-techs" aria-label="Permalink to &quot;Senado vota PEC do fim da escala 6x1 em dia marcado por inflação nos EUA e cortes em big techs&quot;">​</a></h1><p><strong>EDIÇÃO ESPECIAL CONSOLIDADA</strong></p><p><em>Panorama completo de quarta-feira, 14 de outubro de 2026: as decisões em Brasília, os mercados e a economia internacional, os avanços em tecnologia e o fio dos acontecimentos.</em></p><p>Edição Especial Consolidada · quarta-feira, 14 de outubro de 2026 · período 00h00 → 23h59 (Brasília) · 2.933 notícias de 115 fontes consolidadas</p><div class="info custom-block"><p class="custom-block-title">Cobertura</p><p>2.498 notícias representadas de 2.498 elegíveis consolidadas das edições do dia.</p></div><p>O Senado Federal realizou nesta quarta-feira (14) a votação da Proposta de Emenda à Constituição (PEC) que propõe a redução da jornada máxima de trabalho de 44 para 40 horas semanais, garantindo duas folgas remuneradas e marcando o avanço legislativo do debate sobre o fim da escala 6x1 no Brasil.</p><p>A proposta prevê uma transição gradual preservando os salários atuais. Ao longo do dia, as articulações ganharam tração com a formação de quórum de assinaturas e declarações de líderes de diferentes campos partidários, tornando-se o assunto político central do país. Caso aprovada nos dois turnos regimentais, a emenda segue para promulgação do Congresso Nacional.</p><blockquote><p>Finalmente, o povo brasileiro vai conquistar o fim da escala 6 X 1</p><p>— Lula</p></blockquote><p><em>Fontes: <a href="https://veja.abril.com.br/economia/ao-vivo-senado-vota-pec-do-fim-da-escala-6x1/" target="_blank" rel="noreferrer">Economia – VEJA</a> · <a href="https://www.jota.info/trabalho/pec-do-fim-da-escala-6x1-chega-a-votacao-no-senado-relembre-passo-a-passo" target="_blank" rel="noreferrer">JOTA Jornalismo - Feed</a> · <a href="https://www.poder360.com.br/poder-eleicoes-2026/governo-lula-diz-ter-assinaturas-para-acelerar-votacao-da-6-x-1/" target="_blank" rel="noreferrer">Poder360</a></em></p><h2 id="numeros-do-dia" tabindex="-1">Números do Dia <a class="header-anchor" href="#numeros-do-dia" aria-label="Permalink to &quot;Números do Dia&quot;">​</a></h2><ul><li><strong>Dólar:</strong> R$ 5,03 (+0,11%)</li><li><strong>Ibovespa:</strong> 206.947 (+0,04%)</li><li><strong>Selic:</strong> 13,75% a.a.</li><li><strong>Inflação nos EUA (CPI):</strong> 3,7% acumulada em 12 meses (+0,6% no mês de setembro)</li><li><strong>Cortes na Netflix:</strong> 1.000 profissionais (6% do quadro global)</li><li><strong>Endereços sem número no Brasil:</strong> 24,4 milhões de domicílios (22,8% do total)</li></ul><h2 id="destaques-consolidados" tabindex="-1">Destaques Consolidados <a class="header-anchor" href="#destaques-consolidados" aria-label="Permalink to &quot;Destaques Consolidados&quot;">​</a></h2><p><strong>ECONOMIA GLOBAL</strong></p><h3 id="inflacao-nos-eua-acelera-em-setembro-e-atinge-3-7-ao-ano" tabindex="-1">Inflação nos EUA acelera em setembro e atinge 3,7% ao ano <a class="header-anchor" href="#inflacao-nos-eua-acelera-em-setembro-e-atinge-3-7-ao-ano" aria-label="Permalink to &quot;Inflação nos EUA acelera em setembro e atinge 3,7% ao ano&quot;">​</a></h3><p>O índice de preços ao consumidor (CPI) dos Estados Unidos subiu 0,6% em setembro, acumulando 3,7% na taxa anualizada. Puxado principalmente pela alta nos preços dos combustíveis e da energia, o indicador superou as projeções de analistas em Wall Street e aumentou a cautela em relação à trajetória das taxas de juros do Federal Reserve.</p><p><em>Fontes: <a href="https://www1.folha.uol.com.br/mercado/2026/10/inflacao-nos-eua-acelera-em-setembro-e-chega-a-37-nos-ultimos-12-meses.shtml" target="_blank" rel="noreferrer">Folha de S.Paulo - Mercado -</a> · <a href="https://www.aljazeera.com/economy/2026/10/14/us-inflation-rises-before-midterm-elections-fuelling-rate-hike-fears?traffic_source=rss" target="_blank" rel="noreferrer">Al Jazeera – Breaking News</a> · <a href="https://jornaldebrasilia.com.br/cpi-dos-eua-sobe-06-em-setembro-ante-agosto-e-avanca-37-no-comparativo-anual/" target="_blank" rel="noreferrer">Jornal de Brasília</a></em></p><p><strong>AVIAÇÃO &amp; DEFESA</strong></p><h3 id="embraer-formaliza-compra-de-51-da-fabricante-indiana-nal" tabindex="-1">Embraer formaliza compra de 51% da fabricante indiana NAL <a class="header-anchor" href="#embraer-formaliza-compra-de-51-da-fabricante-indiana-nal" aria-label="Permalink to &quot;Embraer formaliza compra de 51% da fabricante indiana NAL&quot;">​</a></h3><p>Em movimento estratégico para expandir sua cadeia produtiva e atendimento no continente asiático, a Embraer celebrou acordo para assumir o controle de 51% da empresa indiana NAL (Novavayu Aerospace Limited) pelo valor de R$ 27 milhões. A operação posiciona a fabricante aeroespacial brasileira em projetos globais de componentes estruturais e defesa.</p><p><em>Fontes: <a href="https://www.poder360.com.br/poder-justica/ao-vivo-stf-julga-lei-que-restringe-onibus-por-aplicativos/" target="_blank" rel="noreferrer">Poder360</a> · <a href="https://exame.com/invest/mercados/ibovespa-amplia-perdas-com-inflacao-nos-eua-e-eleicao-no-radar-dolar-sobe/" target="_blank" rel="noreferrer">Exame</a></em></p><p><strong>BIG TECHS &amp; GAMES</strong></p><h3 id="netflix-e-ubisoft-realizam-novas-rodadas-de-demissoes" tabindex="-1">Netflix e Ubisoft realizam novas rodadas de demissões <a class="header-anchor" href="#netflix-e-ubisoft-realizam-novas-rodadas-de-demissoes" aria-label="Permalink to &quot;Netflix e Ubisoft realizam novas rodadas de demissões&quot;">​</a></h3><p>A Netflix anunciou o corte de aproximadamente 1.000 colaboradores (6% de seus funcionários globais), a maior redução de equipe da plataforma de streaming desde 2022. No universo dos games, a Ubisoft encerrou as atividades do estúdio RedLynx, tradicional desenvolvedor da franquia Trials, com a demissão de 70 profissionais em Singapura como parte do plano de contenção de custos operacionais.</p><p><em>Fontes: <a href="https://g1.globo.com/trabalho-e-carreira/noticia/2026/10/14/netflix-cortes.ghtml" target="_blank" rel="noreferrer">g1 &gt; Tecnologia</a> · <a href="https://www.nytimes.com/2026/10/14/business/media/netflix-layoffs-ted-sarandos.html" target="_blank" rel="noreferrer">NYT &gt; Technology</a> · <a href="https://www.videogameschronicle.com/news/ubisoft-is-planning-to-shut-down-trials-studio-redlynx-and-lay-off-70-ubisoft-singapore-staff/" target="_blank" rel="noreferrer">VGC</a></em></p><h2 id="o-fio-do-dia" tabindex="-1">O Fio do Dia <a class="header-anchor" href="#o-fio-do-dia" aria-label="Permalink to &quot;O Fio do Dia&quot;">​</a></h2><h3 id="a-evolucao-da-pec-da-jornada-de-trabalho-no-congresso" tabindex="-1">A evolução da PEC da jornada de trabalho no Congresso <a class="header-anchor" href="#a-evolucao-da-pec-da-jornada-de-trabalho-no-congresso" aria-label="Permalink to &quot;A evolução da PEC da jornada de trabalho no Congresso&quot;">​</a></h3><ul><li><strong>06h00</strong> · Articulação política inicia coleta de assinaturas para regime de urgência em dois turnos na Mesa Diretora do Senado.</li><li><strong>11h30</strong> · Líderes de bancadas, incluindo oposição e situação, sinalizam apoio à discussão da transição para 40 horas semanais.</li><li><strong>15h00</strong> · Sessão do plenário do Senado abre ordem do dia com quórum qualificado e pronunciamentos favoráveis à votação imediata.</li></ul><h3 id="a-reacao-dos-mercados-a-inflacao-americana" tabindex="-1">A reação dos mercados à inflação americana <a class="header-anchor" href="#a-reacao-dos-mercados-a-inflacao-americana" aria-label="Permalink to &quot;A reação dos mercados à inflação americana&quot;">​</a></h3><ul><li><strong>09h30</strong> · Divulgação do CPI com alta de 0,6% provoca abertura negativa nos futuros de Nova York e elevação nas taxas de rendimento dos títulos do Tesouro dos EUA.</li><li><strong>12h00</strong> · Ibovespa recua mais de 1% refletindo aversão a risco e receio de taxas elevadas no Fed, compensado apenas pelo barril de petróleo.</li><li><strong>17h00</strong> · Ações de commodities e exportadoras sustentam recuperação no fechamento da B3, estabilizando o índice nos 206.947 pontos.</li></ul><h2 id="politica" tabindex="-1">Política <a class="header-anchor" href="#politica" aria-label="Permalink to &quot;Política&quot;">​</a></h2><p><strong>LEGISLATIVO</strong></p><h3 id="aliancas-no-senado-asseguram-calendario-celere-para-votacao-trabalhista" tabindex="-1">Alianças no Senado asseguram calendário célere para votação trabalhista <a class="header-anchor" href="#aliancas-no-senado-asseguram-calendario-celere-para-votacao-trabalhista" aria-label="Permalink to &quot;Alianças no Senado asseguram calendário célere para votação trabalhista&quot;">​</a></h3><p>A apreciação célere da PEC do fim da escala 6x1 contou com apoio de lideranças do governo e da oposição. Senadores como Flávio Bolsonaro (PL-RJ) manifestaram voto favorável, acompanhando a tendência majoritária de bancadas em torno da redução do limite constitucional da jornada semanal.</p><p><em>Fontes: <a href="https://www.poder360.com.br/poder-eleicoes-2026/flavio-diz-que-maioria-do-pl-deve-apoiar-o-fim-da-escala-6-x-1/" target="_blank" rel="noreferrer">Poder360</a> · <a href="https://www1.folha.uol.com.br/blogs/brasilia-hoje/2026/10/lula-e-aconselhado-por-aliados-e-avalia-ir-ao-senado-caso-fim-da-6x1-seja-aprovado.shtml" target="_blank" rel="noreferrer">Folha de S.Paulo - Poder</a></em></p><p><strong>ELEIÇÕES 2026</strong></p><h3 id="justica-eleitoral-prepara-mais-de-114-mil-urnas-em-sao-paulo-para-o-segundo-turno" tabindex="-1">Justiça Eleitoral prepara mais de 114 mil urnas em São Paulo para o segundo turno <a class="header-anchor" href="#justica-eleitoral-prepara-mais-de-114-mil-urnas-em-sao-paulo-para-o-segundo-turno" aria-label="Permalink to &quot;Justiça Eleitoral prepara mais de 114 mil urnas em São Paulo para o segundo turno&quot;">​</a></h3><p>O Tribunal Regional Eleitoral de São Paulo deu início aos testes públicos e preparação física de 114 mil urnas eletrônicas para a disputa de segundo turno. Paralelamente, pesquisas de intenção de voto revelaram cenários competitivos em governos estaduais, com Omar Aziz (PSD) registrando 51% contra 37% de Professora Maria do Carmo (PL) no Amazonas.</p><p><em>Fontes: <a href="https://agenciabrasil.ebc.com.br/politica/noticia/2026-10/estado-de-sp-comeca-preparar-mais-de-114-mil-urnas-para-o-2o-turno" target="_blank" rel="noreferrer">Feed Últimas</a> · <a href="https://www1.folha.uol.com.br/poder/2026/10/quaest-omar-aziz-psd-tem-51-ante-37-de-maria-do-carmo-pl-no-amazonas.shtml" target="_blank" rel="noreferrer">Folha de S.Paulo - Poder</a></em></p><p><strong>Notas de Política</strong></p><ul><li>Procuradoria-Geral da República manifestou-se contrária ao afastamento cautelar do diretor-geral da Polícia Federal no STF.</li><li>Polícia Federal e ministros da Suprema Corte estabeleceram protocolo conjunto para triagem e inclusão de menções a autoridades em relatórios policiais.</li><li>TSE recebeu representação jurídica sobre veiculação de peças eleitorais produzidas por inteligência artificial em plataformas digitais.</li></ul><h2 id="economia-negocios" tabindex="-1">Economia &amp; Negócios <a class="header-anchor" href="#economia-negocios" aria-label="Permalink to &quot;Economia &amp; Negócios&quot;">​</a></h2><p><strong>MERCADO INTERNO</strong></p><h3 id="custo-logistico-nacional-alcanca-r-2-2-trilhoes-em-2026" tabindex="-1">Custo logístico nacional alcança R$ 2,2 trilhões em 2026 <a class="header-anchor" href="#custo-logistico-nacional-alcanca-r-2-2-trilhoes-em-2026" aria-label="Permalink to &quot;Custo logístico nacional alcança R$ 2,2 trilhões em 2026&quot;">​</a></h3><p>Estudo divulgado pelo Instituto ILOS apontou que o custo com transporte, armazenagem e administração de estoques no Brasil atingiu o patamar de 16,1% do PIB. Economistas ressaltam que gargalos em infraestrutura continuam a pressionar as margens das empresas, em paralelo a revisões nas projeções para o PIB do 3º trimestre após desaceleração no setor de serviços.</p><p><em>Fontes: <a href="https://veja.abril.com.br/economia/custo-logistico-no-brasil-deve-chegar-a-r-22-trilhoes-em-2026/" target="_blank" rel="noreferrer">Economia – VEJA</a> · <a href="https://www.infomoney.com.br/economia/queda-de-servicos-em-agosto-reforca-leituras-de-pib-estagnado-no-3o-trimestre/" target="_blank" rel="noreferrer">InfoMoney</a></em></p><p><strong>COMÉRCIO EXTERIOR</strong></p><h3 id="exportacoes-da-china-avancam-36-3-impulsionadas-por-veiculos-e-semicondutores" tabindex="-1">Exportações da China avançam 36,3% impulsionadas por veículos e semicondutores <a class="header-anchor" href="#exportacoes-da-china-avancam-36-3-impulsionadas-por-veiculos-e-semicondutores" aria-label="Permalink to &quot;Exportações da China avançam 36,3% impulsionadas por veículos e semicondutores&quot;">​</a></h3><p>O comércio exterior chinês registrou expansão de 36,3% em setembro, acumulando superávit de US$ 938,1 bilhões de janeiro a setembro. A forte demanda internacional por chips e automóveis elétricos manteve as vendas chinesas em patamares recordes, apesar das tarifas e restrições comerciais no ocidente.</p><p><em>Fontes: <a href="https://veja.abril.com.br/economia/exportacoes-da-china-saltam-363-e-aproximam-superavit-de-novo-recorde/" target="_blank" rel="noreferrer">Economia – VEJA</a></em></p><p><strong>Notas de Economia</strong></p><ul><li>Governo federal detalhou critérios em análise para o programa de renegociação de dívidas do MEI com foco em 2027.</li><li>Agências internacionais de energia alertam que restrições nas refinarias do Oriente Médio podem prolongar aperto no mercado de diesel.</li><li>Cristiano Ronaldo oficializou investimento de R$ 112 milhões em fábrica de envase de água mineral em Portugal.</li></ul><h2 id="tecnologia-seguranca" tabindex="-1">Tecnologia &amp; Segurança <a class="header-anchor" href="#tecnologia-seguranca" aria-label="Permalink to &quot;Tecnologia &amp; Segurança&quot;">​</a></h2><p><strong>SEGURANÇA DA INFORMAÇÃO</strong></p><h3 id="microsoft-publica-maior-atualizacao-da-historia-com-1-416-vulnerabilidades-corrigidas" tabindex="-1">Microsoft publica maior atualização da história com 1.416 vulnerabilidades corrigidas <a class="header-anchor" href="#microsoft-publica-maior-atualizacao-da-historia-com-1-416-vulnerabilidades-corrigidas" aria-label="Permalink to &quot;Microsoft publica maior atualização da história com 1.416 vulnerabilidades corrigidas&quot;">​</a></h3><p>O Patch Tuesday de outubro da Microsoft corrigiu um volume recorde de 1.416 falhas no Windows e sistemas corporativos, incluindo vulnerabilidades críticas do tipo zero-day com exploração ativa no ecossistema e rotinas de bypass de segurança.</p><p><em>Fontes: <a href="https://www.darkreading.com/vulnerabilities-threats/zero-days-microsoft-october-patch-tuesday" target="_blank" rel="noreferrer">darkreading</a></em></p><p><strong>PLATAFORMAS DIGITAIS</strong></p><h3 id="whatsapp-passa-a-permitir-entrada-em-chamadas-para-quem-nao-tem-conta" tabindex="-1">WhatsApp passa a permitir entrada em chamadas para quem não tem conta <a class="header-anchor" href="#whatsapp-passa-a-permitir-entrada-em-chamadas-para-quem-nao-tem-conta" aria-label="Permalink to &quot;WhatsApp passa a permitir entrada em chamadas para quem não tem conta&quot;">​</a></h3><p>A Meta liberou atualização no WhatsApp permitindo que convidados ingressem em chamadas de áudio e vídeo mesmo sem possuir conta ou aplicativo instalado. A conexão é realizada diretamente por navegadores web com aprovação do anfitrião da sala para grupos de até 32 participantes.</p><p><em>Fontes: <a href="https://about.fb.com/news/2026/10/introducing-whatsapp-guest-calling/" target="_blank" rel="noreferrer">Newsroom | Meta Newsroom</a> · <a href="https://sbtnews.sbt.com.br/noticia/economia/whats-app-libera-ligacoes-com-quem-nao-tem-conta-no-aplicativo" target="_blank" rel="noreferrer">SBT News</a></em></p><p><strong>INTELIGÊNCIA ARTIFICIAL &amp; HARDWARE</strong></p><h3 id="antigravity-sdk-amplia-suporte-a-modelos-locais-e-apple-watch-series-12-estreia-no-pais" tabindex="-1">Antigravity SDK amplia suporte a modelos locais e Apple Watch Series 12 estreia no país <a class="header-anchor" href="#antigravity-sdk-amplia-suporte-a-modelos-locais-e-apple-watch-series-12-estreia-no-pais" aria-label="Permalink to &quot;Antigravity SDK amplia suporte a modelos locais e Apple Watch Series 12 estreia no país&quot;">​</a></h3><p>A Google liberou suporte nativo a inferência local no SDK Antigravity, promovendo privacidade de código e eficiência de recursos para agentes autônomos. No mesmo dia, o Censo revelou que 22,8% dos domicílios brasileiros ainda não contam com numeração formal, trazendo desafios para a automação logística. No varejo, a Apple iniciou as vendas dos relógios Watch Series 12 e Ultra 4 no Brasil com chip S11 e biometria aprimorada.</p><p><em>Fontes: <a href="https://www.infoq.com/news/2026/10/antigravity-sdk-local-models/?utm_campaign=infoq_content&amp;utm_source=infoq&amp;utm_medium=feed&amp;utm_term=global" target="_blank" rel="noreferrer">InfoQ</a> · <a href="https://tiinside.com.br/14/10/2026/quase-25-dos-enderecos-no-brasil-nao-tem-numeros-e-isso-e-um-problema-para-os-agentes-de-ia/" target="_blank" rel="noreferrer">TI INSIDE Online</a> · <a href="https://www.tudocelular.com/apple/noticias/n265074/apple-watch-series-12-ultra-4-brasil-chip-bateria.html" target="_blank" rel="noreferrer">Tudocelular.com</a></em></p><p><strong>Notas de Tecnologia</strong></p><ul><li>Sony revelou o microfone sem fio profissional ECM-W5 com gravação interna em 32-bit float.</li><li>Xbox apresentou novo controle compacto Nano Controller por 49,99 euros.</li><li>Ministério da Cultura e governo anunciaram edital de R$ 200 milhões para fomento à produção de games nacionais.</li></ul><h2 id="mundo" tabindex="-1">Mundo <a class="header-anchor" href="#mundo" aria-label="Permalink to &quot;Mundo&quot;">​</a></h2><p><strong>ENERGIA &amp; DIPLOMACIA</strong></p><h3 id="trump-propoe-concessoes-de-petroleo-e-gas-na-groenlandia" tabindex="-1">Trump propõe concessões de petróleo e gás na Groenlândia <a class="header-anchor" href="#trump-propoe-concessoes-de-petroleo-e-gas-na-groenlandia" aria-label="Permalink to &quot;Trump propõe concessões de petróleo e gás na Groenlândia&quot;">​</a></h3><p>O presidente Donald Trump defendeu plano para exploração de recursos fósseis em grande escala no território ártico da Groenlândia, gerando reações imediatas de autoridades ambientais e diplomáticas dinamarquesas.</p><p><em>Fontes: <a href="https://agenciabrasil.ebc.com.br/internacional/noticia/2026-10/trump-anuncia-exploracao-de-petroleo-e-gas-na-groenlandia" target="_blank" rel="noreferrer">Feed Últimas</a></em></p><p><strong>Notas Internacionais</strong></p><ul><li>Presidência do Museu do Louvre alertou para risco iminente de suspensão de visitação sem orçamento para obras estruturais e modernização.</li><li>Quênia confirmou segundo caso de contaminação por vírus Ebola sob protocolo de contenção sanitária.</li><li>Protestos estudantis na Albânia resultaram em confronto e danos na sede do Ministério da Educação.</li></ul><h2 id="quiz-do-dia" tabindex="-1">Quiz do Dia <a class="header-anchor" href="#quiz-do-dia" aria-label="Permalink to &quot;Quiz do Dia&quot;">​</a></h2><ol><li><p><strong>Qual é o teor central da PEC votada pelo Senado nesta quarta-feira?</strong></p><ul><li>[x] Redução da jornada máxima para 40 horas semanais e fim da escala 6x1</li><li>[ ] Aumento da idade mínima de aposentadoria</li><li>[ ] Unificação do FGTS com o seguro-desemprego</li></ul></li><li><p><strong>Para qual valor acumulado acelerou a taxa de inflação (CPI) nos EUA em setembro?</strong></p><ul><li>[ ] 2,4%</li><li>[x] 3,7%</li><li>[ ] 5,1%</li></ul></li><li><p><strong>Qual percentual do quadro de colaboradores a Netflix dispensou em sua reestruturação?</strong></p><ul><li>[x] 6% (aproximadamente 1.000 empregados)</li><li>[ ] 15%</li><li>[ ] 1%</li></ul></li></ol><hr><p><em>Edição Especial consolidada às 20h00 pelo sistema editorial automatizado de O Fio.</em></p>',77)])])}const h=e(s,[["render",t]]);export{u as __pageData,h as default};
